namespace CardPlatform.Settlement.Job.ReadModel;

/// <summary>A row of the ledger <c>entries</c> table: one debit or credit of one account within a transaction.</summary>
public sealed class EntryRecord
{
    /// <summary>The identity generated by the database, increasing in insertion order.</summary>
    public long Id { get; init; }

    public Guid TransactionId { get; init; }

    public TransactionRecord Transaction { get; init; } = null!;

    public Guid AccountId { get; init; }

    public AccountRecord Account { get; init; } = null!;

    /// <summary>The direction as stored by the Ledger: <c>Debit</c> or <c>Credit</c>.</summary>
    public string Direction { get; init; } = string.Empty;

    /// <summary>Amount in major units of <see cref="Currency"/>, always positive.</summary>
    public decimal Amount { get; init; }

    /// <summary>ISO 4217 code of the amount.</summary>
    public string Currency { get; init; } = string.Empty;
}
